"""Read-only post-run checks and append-only experiment report/log completion."""
from .common import *
import json,collections,fcntl

def main(run_id='smoke_v2'):
    run=C/'artifacts'/run_id
    status=json.loads((run/'status.json').read_text());ledger=json.loads((C/'artifacts/gpu_ledger.json').read_text());driver=json.loads((C/'artifacts/driver_v3_status.json').read_text());cache=json.loads((C/'artifacts/features_v3/READY_features.json').read_text());tests=(C/'artifacts/contracts_release_v8.log').read_text()
    assert status['status']=='smoke_completed' and driver['status']=='completed';assert ledger['elapsed_s']<=10800 and not ledger.get('active');assert 'failed' not in tests and 'passed' in tests
    stages=json.loads((run/'stage_results.json').read_text());parameters=json.loads((run/'parameters.json').read_text());metrics=json.loads((run/'dev_metrics.json').read_text());nolanguage=json.loads((run/'dev_metrics_trained_no_language.json').read_text());profile=json.loads((run/'profile32_v1/READY_profile.json').read_text());latency=json.loads((run/'latency_v1/READY_latency.json').read_text());resumes={s:json.loads((run/(s+'_resume_check.json')).read_text()) for s in stages}
    for x in resumes.values():assert x['identical_loss'] and x['max_parameter_error']==0
    for x in stages.values():assert x['loss_finite'] and x['sample_counts']['demo3_count']<=.45*x['sample_counts']['count']
    for x in latency['results']:assert x['full_pipeline']['calls']>=200
    lines=['## 实现与执行最终记录（'+brt()+'）','', '### 实现、参数与token',json.dumps(parameters,ensure_ascii=False,indent=2),'','O = 当前24 + 历史32 + NULL1 +指令句组数，常用短指令O58；A51（状态1+动作50）；W72；action_only109（短指令），joint181，P1 O+W130。实际长指令按句组数增加。固定SigLIP2空间2×4目标不随attention pooling学习，stop-grad；learned8观测池化在共享core前。核心参数及总量见上。状态仅进A，P1不调用状态/动作投影；动作12关节当前q残差，夹爪signed absolute。默认action_only物理删除W，joint可开。质量token/权重默认关闭且有合同测试。','', '### CPU合同最终结果','```text',tests.strip()[-2600:],'```','','覆盖O只读O与梯度隔离、A/W互读、W删除不调用投影、状态只进A、历史丢弃与源范围mask、残差/signed夹爪、冻结真实encoder零梯度、真实encoder缓存/非缓存策略输出一致、demo3窗口累计硬上限、P3批准收据与V1严格门、rev4全parent隔离、READY源文件/收据自身篡改拒绝、模式损失反传、quality接口、CPU不碰CUDA RNG、精确恢复。','', '### 缓存与语言统计',json.dumps(cache,ensure_ascii=False,indent=2),'','新缓存每相机帧8×768 fp16，沿用E84完整视野保比例bilinear/edge-pad/0.5归一化，固定224；先剔除padding再固定池化到2×4。不是官方直接方形拉伸。E84时序缓存大多只有global，不冒用为空间缓存；本轮最初3capture结果以只读符号链接复用，无大文件复制。P1/P3共用源帧去重缓存，源stat提取前后相同，未改同事目录。文本只来自train的E83完整指令及精确锚点FK/E83对齐项；dev原人工短指令是固定任务条件，未为dev/test做模型语言标注。','','### 烟雾固定结束结果',json.dumps(stages,ensure_ascii=False,indent=2),'','恢复重放（所有阶段下一优化步loss/参数精确相同）：',json.dumps(resumes,ensure_ascii=False,indent=2),'','P1 192步、P3 384步、同一P1和相同数据/采样/RNG/步数无语言384步，batch8；不按任何模型标签、dev指标或loss选择checkpoint。P3无语言关闭指令条件与语言对齐监督；推理去语言另记。仅验证工程与优化，不作语言有效性或WAM收益结论。','','### dev真实反馈离线误差','6 parent、48窗口，parent等权；原始next-frame follower反馈为真值，未作标签平移。角度误差是12关节平均绝对误差rad→deg换算，不是TCP方向误差；夹爪mm单独报告，不将rad/m裸平均。','', '|设置|前8关节L1(rad)|前8角度(°)|前8夹爪(mm)|H50关节L1(rad)|H50角度(°)|H50夹爪(mm)|','|---|---:|---:|---:|---:|---:|---:|']
    for name in ('copy_current_state','action_only','joint','no_language_inference'):
        a=metrics['results'][name+'_8'];b=metrics['results'][name+'_50'];lines.append('|'+name+'|'+'|'.join(f'{x:.6f}' for x in (a['joint_L1_rad'],a['joint_angle_deg'],a['gripper_L1_mm'],b['joint_L1_rad'],b['joint_angle_deg'],b['gripper_L1_mm']))+'|')
    a=nolanguage['results']['action_only_8'];b=nolanguage['results']['action_only_50'];lines.append('|trained_no_language|'+'|'.join(f'{x:.6f}' for x in (a['joint_L1_rad'],a['joint_angle_deg'],a['gripper_L1_mm'],b['joint_L1_rad'],b['joint_angle_deg'],b['gripper_L1_mm']))+'|')
    lines+=['','这些是小规模固定stage-end的离线烟雾参考；独立parent只有6，不能做checkpoint选型、成功率或因果命令模型结论。','','### GPU时延与正式GPUh外推',json.dumps(latency,ensure_ascii=False,indent=2),json.dumps(profile,ensure_ascii=False,indent=2),'','每模式≥200次计分、8次预热，四固定噪声×10Euler。full_pipeline含真实三路视频原位解码、CPU预处理、GPU冻结视觉编码、缓存历史/原人工指令、状态可得等待回放及策略；另报告缓存特征策略时间。离线回放不等于实机调度与网络/传感器排队验收。正式估算取batch32实测100更新/阶段（含读缓存、数据装配、guard检查和优化），P1=5000步、P3=10000步；未启动正式训练。','','### GPU账本',json.dumps(ledger,ensure_ascii=False,indent=2),'','所有提取/探针/训练/profile/时延采用单卡、free≥估算峰值16GB×1.5准入；未改他人进程、未用MPS。首轮串行提取按预测超预算自动停，全部调试计入3GPUh；没有OOM。','','### 与E82-M差异、未完成与需用户决定','- DINOv2/LoRA/整数任务条件替换为冻结SigLIP2双塔/语言；视觉224、每当前相机8、历史图像4×8；删除实测q历史和历史动作输入，状态挪至A。世界固定空间目标72token，增加确定性余弦头与小权重对齐；默认不生成未来。','- 数据改为rev4 P1与用户冻结V1 P3；落实demo3按采样窗口≤45%。模型筛选只定义训练池，不作真值/阈值/选型；不改code_e82。','- 未完成：P1 的 piper_4dc107335389f5711a0f65e0（demo3 episode142）左腕两份别名均Permission denied，1794窗隔离，可读P1=107057；冻结P3 V1不受影响，24477窗不变。未修改他人权限，未用零图伪造可读帧。需源所有者恢复读取后另补缓存，或另版批准两视角mask。正式训练（本轮禁止）、新盲测/实机成功率、充分seed与有统计效力的语言消融、真实在线传感器/状态同步验收；冻结224对尖端/孔口的能力仍有限。','- 需要用户决定：正式配方中干净动作25%与模式表10%的含义仍需锁定。本轮暂定主模式30/30/30/10，另在同步/独立W更新中25%概率加干净动作辅助调用，已写run contract；不把暂定解释当正式配方。','', '状态：实现、CPU合同、可读来源缓存、有界烟雾、dev参考误差、GPU时延及估算完成；正式训练未启动。']
    append_report('\n'.join(lines))
    receipt=dict(status='complete_smoke_only',run_id=run_id,updated_brt=brt(),gpu_hours=ledger['elapsed_s']/3600,test_summary=tests.strip().splitlines()[-1],P1_windows=107057,P3_windows=24477,formal_started=False,files=[dict(path=str(x),sha256=sha(x)) for x in [run/'status.json',run/'dev_metrics.json',run/'dev_metrics_trained_no_language.json',run/'profile32_v1/READY_profile.json',run/'latency_v1/READY_latency.json',C/'artifacts/gpu_ledger.json']]);atomic(C/'artifacts/E86_M_COMPLETE.json',receipt)
    for name,text in [('docs/experiment_log/EXPERIMENT_LOG.md','\n## E86-M — 2026-11-13 BRT（完成烟雾）\n目标：Piper v3冻结SigLIP2语言条件统一WAM。改动：code_e86模型/数据/采样/损失/训练恢复/评估；P3_ready_V1用户批准收据。命令：python -m e86.cache_fast / e86.driver / pytest；目录：code_e86/artifacts/'+run_id+'，notes/e86_M_v3_smoke_20261113.md。结果：'+receipt['test_summary']+'；P1可读107057（rev4原108851）/P3 V1 24477窗口；可读来源缓存完成（P1隔离1794窗）；GPU墙钟'+str(round(receipt['gpu_hours'],6))+'GPUh；dev48窗与两模式各200次时延已测。结论：工程烟雾完成，固定stage-end不做选型，不外推实机性能。状态：complete_smoke_only；正式训练未启动；25%/10%模式含义待用户锁定。时间 '+brt()+'。\n'),('notes/worklog.md','\n- '+brt()+' E86-M完成：'+receipt['test_summary']+'；rev4 P1/V1 P3可读来源缓存与固定P1/P3/无语言烟雾、48 dev窗、两模式各200次GPU时延；'+str(round(receipt['gpu_hours'],6))+'GPUh<3；无正式训练。见notes/e86_M_v3_smoke_20261113.md。\n')]:
        with (T/name).open('a') as f:fcntl.flock(f,fcntl.LOCK_EX);f.write(text)
    print(json.dumps(receipt,ensure_ascii=False),flush=True)
if __name__=='__main__':main()
